def comps(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx] and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                out.append(cells)
    return out
