def info(g):
    res=[]
    for cs in comps(g):
        rs=[r for r,c in cs]; cl=[c for r,c in cs]
        h,w=max(rs)-min(rs)+1,max(cl)-min(cl)+1
        sub=[[g[r][c] for c in range(min(cl),max(cl)+1)] for r in range(min(rs),max(rs)+1)]
        n9=sum(v==9 for row in sub for v in row)
        hs = sub==[r[::-1] for r in sub]
        vs = sub==sub[::-1]
        res.append((h,w,len(cs),n9,hs,vs))
    return res
